@namespace sv_33ae3320b8b24fc387cfb8341005d0f8.Components.Pages.Settings
@using sv_33ae3320b8b24fc387cfb8341005d0f8.Models
@using sv_33ae3320b8b24fc387cfb8341005d0f8.Services
@inject ISettingsService SettingsService

<div class="settings-section security-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-row">
                <label class="toggle-label">
                    <input type="checkbox" checked="@_twoFactorEnabled" @onchange="ToggleTwoFactor" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Enable Two-Factor Authentication
                </label>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions" CurrentSessionId="sess-1" OnRevoke="HandleRevoke" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSecurity();
    }

    private async Task LoadSecurity()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
        _loading = false;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _lastPasswordChange = DateTime.UtcNow;
    }

    private void ToggleTwoFactor(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task HandleRevoke(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}

