@namespace sv_33ae3320b8b24fc387cfb8341005d0f8.Components.Pages.Settings
@using sv_33ae3320b8b24fc387cfb8341005d0f8.Models
@using sv_33ae3320b8b24fc387cfb8341005d0f8.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            @theme
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            @size
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Language</h3>
                <select @bind="_language" class="form-control">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <div class="form-group">
                <h3>Compact Mode</h3>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Enable compact mode
                </label>
            </div>

            <div class="live-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p>Theme: <strong>@_theme</strong> | Font: <strong>@_fontSize</strong> | Language: <strong>@_language</strong></p>
                @if (_compactMode)
                {
                    <p><em>Compact mode is enabled — reduced spacing.</em></p>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast-message success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
            "System" => "background-color: #f0f0f0; color: #333;",
            _ => "background-color: #ffffff; color: #333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 12px;",
            "Large" => "font-size: 18px;",
            _ => "font-size: 14px;"
        };

        var padding = _compactMode ? "padding: 8px;" : "padding: 16px;";

        return $"{bg} {font} {padding} border: 1px solid #ccc; border-radius: 8px; margin-top: 16px;";
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

