+                    @foreach (var theme in new[] { "Light", "Dark", "System" })
+                    {
+                        <label class="radio-label">
+                            <input type="radio" name="theme" value="@theme"
+                                   checked="@(_theme == theme)"
+                                   @onchange="() => _theme = theme" />
+                            @theme
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <div class="form-group">
+                <h3>Font Size</h3>
+                <div class="radio-group">
+                    @foreach (var size in new[] { "Small", "Medium", "Large" })
+                    {
+                        <label class="radio-label">
+                            <input type="radio" name="fontSize" value="@size"
+                                   checked="@(_fontSize == size)"
+                                   @onchange="() => _fontSize = size" />
+                            @size
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <div class="form-group">
+                <h3>Language</h3>
+                <select @bind="_language" class="form-control">
+                    <option value="English">English</option>
+                    <option value="Spanish">Spanish</option>
+                    <option value="French">French</option>
+                    <option value="German">German</option>
+                    <option value="Japanese">Japanese</option>
+                </select>
+            </div>
+
+            <div class="form-group">
+                <h3>Compact Mode</h3>
+                <label class="toggle-label">
+                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
+                    <span class="toggle-switch"></span>
+                    Enable compact mode
+                </label>
+            </div>
+
+            <div class="live-preview" style="@GetPreviewStyle()">
+                <h4>Live Preview</h4>
+                <p>This is how your content will look with the selected settings.</p>
+                <p>Theme: <strong>@_theme</strong> | Font: <strong>@_fontSize</strong> | Language: <strong>@_language</strong></p>
+                @if (_compactMode)
+                {
+                    <p><em>Compact mode is enabled — reduced spacing.</em></p>
+                }
+            </div>
+
+            <div class="form-actions">
+                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+            </div>
+
+            @if (_showSuccess)
+            {
+                <div class="toast-message success">Appearance settings saved!</div>
+            }
+        </div>
+    }
+</div>
+
+@code {
+    private bool _loading = true;
+    private bool _showSuccess;
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        var settings = await SettingsService.GetAppearanceAsync();
+        _theme = settings.Theme;
+        _fontSize = settings.FontSize;
+        _language = settings.Language;
+        _compactMode = settings.CompactMode;
+        _loading = false;
+    }
+
+    private string GetPreviewStyle()
+    {
+        var bg = _theme switch
+        {
+            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
+            "System" => "background-color: #f0f0f0; color: #333;",
+            _ => "background-color: #ffffff; color: #333;"
+        };
+
+        var font = _fontSize switch
+        {
+            "Small" => "font-size: 12px;",
+            "Large" => "font-size: 18px;",
+            _ => "font-size: 14px;"
+        };
+
+        var padding = _compactMode ? "padding: 8px;" : "padding: 16px;";
+
+        return $"{bg} {font} {padding} border: 1px solid #ccc; border-radius: 8px; margin-top: 16px;";
+    }
+
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        _showSuccess = true;
+        _ = HideToastAfterDelay();
+    }
+
+    private async Task HideToastAfterDelay()
+    {
+        await Task.Delay(3000);
+        _showSuccess = false;
+        await InvokeAsync(StateHasChanged);
+    }
+}
+

toolArgs.file_text:
@page "/settings"
@namespace sv_33ae3320b8b24fc387cfb8341005d0f8.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.1rem;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left-color 0.15s;
    border-left: 3px solid transparent;
    color: #555;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    color: #222;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    font-weight: 500;
    transition: background-color 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover:not(:disabled) {
    background: #bdbdbd;
}

.btn-danger {
    background: #d32f2f;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast messages */
.toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

.toast-message.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-message.error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

/* Profile */
.avatar-area {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url-label {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Toggle switches */
.toggle-row {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-input {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channels */
.channels-section {
    margin-top: 2rem;
}

.channels-section h3 {
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.4rem 0.75rem;
    border-radius: 4px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #f5f5f5;
}

/* Security */
.change-password-panel {
    margin-bottom: 2rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
}

.panel-toggle {
    width: 100%;
    padding: 1rem 1.25rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: background 0.15s;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.panel-content {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

.two-factor-section {
    margin: 2rem 0;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.two-factor-section h3 {
    margin: 0 0 1rem;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
}

.status-indicator {
    font-size: 0.85rem;
    font-weight: 600;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
}

.status-indicator.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-indicator.disabled {
    background: #ffebee;
    color: #c62828;
}

.info-text {
    margin-top: 0.75rem;
    font-size: 0.85rem;
    color: #666;
}

/* Sessions table */
.active-sessions {
    margin-top: 2rem;
}

.active-sessions h3 {
    margin-bottom: 1rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.current-session-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-dialog h4 {
    margin: 0 0 1rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Appearance */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.live-preview {
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

.live-preview h4 {
    margin: 0 0 0.5rem;
}

.live-preview p {
    margin: 0.25rem 0;
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

